### Max Queue Size
```ts
const queue = new Qewe({ maximumQueueSize: 3 });

queue.enqueue('a', 1); // ✅
queue.enqueue('b', 1); // ✅
queue.enqueue('c', 1); // ✅
queue.enqueue('d', 4); // ❌ Error
```

### Explicit Queue Type
```ts
// before
const queue = new Qewe({ minQueue: true });

// after
const queue = new Qewe({ queueType: 'min' });
```

